import fs from 'node:fs/promises'
import {dir,db,asset,send,reviewed} from './reply-runtime-20261007.mjs'
const s=JSON.parse(await fs.readFile(dir+'/reply-refresh.json','utf8')),plans=[];const get=n=>s.threads.find(t=>t.contact.name===n)
for(const name of ['Chanique Keane-Dawes','Angela Makino','ANNA EV BELYNTSEVA','HUA CHEN','SAGAR MATHARU']){const t=get(name),c=t.contact,first=name.split(' ')[0].toLowerCase().replace(/^./,x=>x.toUpperCase());plans.push({id:c.id,name,city:c.city,phone:c.phone,latest:t.touches.at(-1).id,from:'+14374650584',body:`Here you go, ${first}! Here's our ${c.city} card. Feel free to save it and share it when a client needs moving help.`,media_urls:[await asset(c.city)]})}
const lisa=get('LISA ANNE LEWENZA');plans.push({id:lisa.contact.id,name:lisa.contact.name,city:lisa.contact.city,phone:lisa.contact.phone,latest:lisa.touches.at(-1).id,from:'+14374650584',followup_key:'scope-acknowledgement',body:"Thanks Lisa, that's helpful! I've noted the sofas are about 78 and 90 inches, a few steps at your house and a loading dock at the store, with any midday next week working for the move. I've also noted that tomorrow works for a call. We'll review both legs and the access before confirming a price."})
await fs.writeFile(dir+'/1935-reply-plan.json',JSON.stringify(plans,null,2));for(const p of plans)await send(p)
await db('crm_tasks',{id:'eq.evening-20261006-20261007-lisa-sofas'},'PATCH',{title:'Call Lisa Lewenza October 8 — two-way sofa quote',priority:'high',due_at:'2026-10-08T14:00:00Z',description:'Lisa explicitly permits a call tomorrow Oct8, no exact call time agreed. Phone +14168959031. Two-way sofa transfer 168 Kingswood Rd Toronto to 185 Bridgeland Ave North York then another sofa back. Sofas approx78 and90 inches. Few steps at house; store loading dock. Any day next week, midday preferred; Lisa estimates45min each way. Price-sensitive: considering doing it with husband but busy. Ask photos/remaining dimensions and confirm access/date; quote complete two-leg scope. No amount or booking promised.'})
const raluca=get('MARIANA RALUCA NEAGU-RUSU');const [fresh]=await db('market_contacts',{id:'eq.'+raluca.contact.id});await db('market_contacts',{id:'eq.'+fresh.id},'PATCH',{name:'Raluca Neagu-Rusu',notes:(fresh.notes||'')+'\n[2026-10-07 recipient preference] Goes by Raluca. Original imported name: MARIANA RALUCA NEAGU-RUSU.'})
for(const t of s.threads){if(plans.some(p=>p.id===t.contact.id))continue;for(const x of t.touches.filter(x=>x.direction==='inbound'&&!x.metadata?.partnership_review))await reviewed(x.id,t.contact.id===fresh.id?'Preferred name Raluca saved; original identity retained. No additional message needed.':'Acknowledgement/reaction reviewed; existing tasks retained, no extra outbound.')}
await reviewed('a6bb855f-c765-4be3-90b9-e93278916dae','Earlier thanks reviewed; subsequent sofa enquiry handled and owner call task updated.')
console.log('Five cards and Lisa acknowledgement sent; preferred name updated.')
